+package base
+
+import (
+	"strings"
+	"sync"
+	"sync/atomic"
+	"time"
+)
+
+var auditActive atomic.Bool
+var auditMu sync.Mutex
+var auditGrowth map[string]*Growth
+var auditBegin time.Time
+var auditCopyBegin float64
+
+type Growth struct {
+	Calls     int     `json:"calls"`
+	Allocated int64   `json:"allocated_bytes"`
+	Copied    int64   `json:"copied_existing_bytes"`
+	Seconds   float64 `json:"grow_seconds"`
+}
+
+func SnapshotAuditBegin() {
+	auditMu.Lock()
+	auditGrowth = map[string]*Growth{}
+	auditBegin = time.Now()
+	auditCopyBegin = 0
+	auditMu.Unlock()
+	auditActive.Store(true)
+}
+
+// Called with MemFS tree lock held, so traversing node parents is consistent.
+func snapshotAuditGrow(n *memNode, old, end int, elapsed time.Duration) {
+	if !auditActive.Load() {
+		return
+	}
+	parts := []string{}
+	for p := n; p != nil; p = p.parent {
+		parts = append([]string{p.name}, parts...)
+	}
+	name := strings.Join(parts, "/")
+	auditMu.Lock()
+	defer auditMu.Unlock()
+	r := auditGrowth[name]
+	if r == nil {
+		r = &Growth{}
+		auditGrowth[name] = r
+	}
+	r.Calls++
+	r.Allocated += int64(end)
+	r.Copied += int64(old)
+	r.Seconds += elapsed.Seconds()
+}
+func SnapshotAuditReport() map[string]Growth {
+	auditMu.Lock()
+	defer auditMu.Unlock()
+	r := map[string]Growth{}
+	for n, g := range auditGrowth {
+		r[n] = *g
+	}
+	return r
+}
+
+func snapshotAuditDirectory(name string) {
+	if !auditActive.Load() {
+		return
+	}
+	if strings.Trim(name, "/") == "snapshot-out/data" {
+		auditMu.Lock()
+		auditCopyBegin = time.Since(auditBegin).Seconds()
+		auditMu.Unlock()
+	}
+}
+func SnapshotAuditBoundary() float64 { auditMu.Lock(); defer auditMu.Unlock(); return auditCopyBegin }
