@@ -0,0 +1,51 @@
+package main
+
+import (
+	"crypto/sha256"
+	"encoding/json"
+	"example.com/mariamem-spike/generated/base"
+	"flag"
+	"io"
+	"os"
+	"runtime"
+	"syscall"
+	"time"
+)
+
+func main() {
+	size := flag.Int("mib", 96, "file size")
+	chunk := flag.Int("chunk", 65536, "write block")
+	flag.Parse()
+	fs := base.NewMemFS()
+	f, e := fs.OpenFile("file", os.O_CREATE|os.O_RDWR, 0600)
+	if e != nil {
+		panic(e)
+	}
+	p := make([]byte, *chunk)
+	for i := range p {
+		p[i] = byte(42)
+	}
+	runtime.GC()
+	var before, after runtime.MemStats
+	runtime.ReadMemStats(&before)
+	var r0, r1 syscall.Rusage
+	syscall.Getrusage(syscall.RUSAGE_SELF, &r0)
+	base.SnapshotAuditBegin()
+	t := time.Now()
+	n := *size * 1024 * 1024
+	for off := 0; off < n; {
+		count := min(len(p), n-off)
+		if _, e := f.Write(p[:count]); e != nil {
+			panic(e)
+		}
+		off += count
+	}
+	elapsed := time.Since(t).Seconds()
+	syscall.Getrusage(syscall.RUSAGE_SELF, &r1)
+	runtime.ReadMemStats(&after)
+	f.Seek(0, 0)
+	h := sha256.New()
+	io.Copy(h, f)
+	cpu := float64(r1.Utime.Sec-r0.Utime.Sec+r1.Stime.Sec-r0.Stime.Sec) + float64(r1.Utime.Usec-r0.Utime.Usec+r1.Stime.Usec-r0.Stime.Usec)/1e6
+	json.NewEncoder(os.Stdout).Encode(map[string]any{"bytes": n, "chunk": *chunk, "seconds": elapsed, "cpu_seconds": cpu, "allocated_bytes": after.TotalAlloc - before.TotalAlloc, "gc_cycles": after.NumGC - before.NumGC, "sha256": h.Sum(nil), "growth": base.SnapshotAuditReport()})
+}
